// Typed access to the PUBLIC media manifest (generated by scripts/build-media.mjs).
// It never contains source paths — see scripts/lib/public-manifest.mjs.
import manifest from '../data/media.public.json';
import mediaStrings from '../i18n/media.json';
import type { Locale } from '../i18n/config';

/** Translated title/alt per media id, generated from the owner's review file by scripts/i18n/build-media.mjs. */
const TRANSLATED = mediaStrings as Record<string, Partial<Record<Locale, { title?: string; alt?: string }>>>;

export interface MediaItem {
  id: string;
  type: 'image' | 'video';
  sectionId: string;
  brandId?: string;
  title: string;
  alt: string;
  posterSrc: string;
  posterWidth: number;
  posterHeight: number;
  fullImageSrc?: string;
  videoSrc?: string;
  /** short silent loop used for hover preview (gallery, Raw/Final) */
  previewSrc?: string;
  encoded?: boolean;
  width: number;
  height: number;
  aspectRatio: number;
  durationSeconds?: number;
  sortOrder: number;
}

export interface Brand {
  id: string;
  displayName: string;
  sortOrder: number;
  mediaIds: string[];
}

export const mediaItems = manifest.items as MediaItem[];
/** Brands with nothing to show are dropped: Marie and Winnie are video-only folders, and the owner
 * moved every Social Production video out of the scanned tree (2026-10-18), so only brands that
 * still have images reach the rail. */
export const brands = (manifest.brands as Brand[])
  .filter((b) => b.mediaIds.length > 0)
  .sort((a, b) => a.sortOrder - b.sortOrder);
const byId = new Map(mediaItems.map((m) => [m.id, m]));

export const getMedia = (id: string) => byId.get(id);
export const sectionMedia = (sectionId: string) =>
  mediaItems.filter((m) => m.sectionId === sectionId).sort((a, b) => a.sortOrder - b.sortOrder);
export const brandMedia = (brand: Brand) => brand.mediaIds.map((id) => byId.get(id)).filter(Boolean) as MediaItem[];

/**
 * The manifest title/alt in `locale`. Only the two copy fields change — ids, sources, sizes and the
 * "keep" values (brand names, numbers) stay exactly as the pipeline produced them. Vietnamese is the
 * manifest's own language, so it is returned untouched.
 */
export function localizeMedia<T extends MediaItem>(m: T, locale: Locale = 'vi'): T {
  if (locale === 'vi') return m;
  const t = TRANSLATED[m.id]?.[locale];
  if (!t) return m;
  return { ...m, title: t.title ?? m.title, alt: t.alt ?? m.alt };
}

/** `sectionMedia` in a locale (media titles/alts translated, order unchanged). */
export const sectionMediaIn = (sectionId: string, locale: Locale) => sectionMedia(sectionId).map((m) => localizeMedia(m, locale));
/** `brandMedia` in a locale. */
export const brandMediaIn = (brand: Brand, locale: Locale) => brandMedia(brand).map((m) => localizeMedia(m, locale));

/** Video is playable on the web only once encoded (Phase 1 encodes a representative set). */
export const isPlayable = (m: MediaItem) => m.type === 'video' && !!m.encoded && !!m.videoSrc;

export const fmtDuration = (s?: number) => {
  if (!s || !isFinite(s)) return '';
  const m = Math.floor(s / 60);
  return `${m}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
};

/** Data attributes understood by the inline dialog bootstrap (see src/scripts/dialog-bootstrap.js). */
export function openAttrs(m: MediaItem, group: string): Record<string, string> {
  const base: Record<string, string> = {
    'data-dfl-open': m.type,
    'data-media-id': m.id,
    'data-group': group,
    'data-title': m.title,
    'data-poster': m.posterSrc,
    'data-aspect': String(m.aspectRatio),
  };
  if (m.type === 'image') base['data-full-src'] = m.fullImageSrc ?? m.posterSrc;
  else if (isPlayable(m)) base['data-video-src'] = m.videoSrc!;
  else base['data-video-pending'] = '';
  return base;
}
